import{ownerMessage,ownerLeaf,ownerText,ownerMarkup,ownerError,ownerHeading,ownerDate,ownerDateLeaf,ownerPaint,watchOwnerUi,stopOwnerUi,uiMessage,uiLeaf,uiSet,uiRaw,uiAttrs,uiAttribute,uiAttributeAttrs,t,getLocale}from './owner-i18n.js';
const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function mountTeacherAdmin(host,{call,isActive=()=>host.isConnected}={}){
 let disposed=false,busy=false,lookup=0;
 const active=()=>!disposed&&host.isConnected&&isActive();
 ownerPaint(host,"<section class=\"teacher-admin\"><a class=\"button secondary\" href=\"#lesson?view=teacher&return=owner\" data-i18n=\"ownerUi.teacherWorkspace\">Кабинет преподавателя</a><h2 data-i18n=\"ownerUi.assignTeacher\">Назначить преподавателя</h2><p class=\"cabinet-muted\" data-i18n=\"ownerUi.assignTeacherNote\">Назначьте преподавателя по нику его зарегистрированного аккаунта SALAH. Роль сохраняется на сервере. Доступ к новым учебным разделам пока остаётся закрытым.</p><form data-find-teacher><label><span data-i18n=\"ownerUi.salahNickname\">Ник в SALAH</span><input type=\"text\" name=\"nickname\" autocomplete=\"off\" minlength=\"2\" maxlength=\"40\" required placeholder=\"Введите ник преподавателя\" data-i18n-placeholder=\"ownerUi.teacherNicknamePlaceholder\"></label><button type=\"submit\" class=\"button secondary\" data-i18n=\"ownerUi.findAccount\">Найти аккаунт</button></form><p role=\"status\" aria-live=\"polite\" data-teacher-status></p><div data-teacher-profile></div><h3 data-i18n=\"ownerUi.assignedTeachers\">Назначенные преподаватели</h3><div data-teacher-roster></div><p class=\"cabinet-muted\" data-i18n=\"ownerUi.teacherRoleNote\">Роль можно отозвать в любой момент. Права владельца и администратора SALAH не передаются.</p></section>");
 const form=host.querySelector('form'),status=host.querySelector('[data-teacher-status]'),profile=host.querySelector('[data-teacher-profile]'),roster=host.querySelector('[data-teacher-roster]');
 const controls=value=>{busy=value;for(const b of host.querySelectorAll('button,input'))b.disabled=value;};
 function card(account){const el=host.ownerDocument.createElement('article');el.className='teacher-profile cabinet-lesson-card';ownerPaint(el,'<div class="teacher-profile-heading"><div class="cabinet-pupil-avatar" aria-hidden="true" lang="" dir="auto" translate="no">'+escape((account.nickname||'У').slice(0,1).toUpperCase())+'</div><div><h3 lang="" dir="auto" translate="no">'+escape(account.nickname)+'</h3><p class="teacher-email"><span lang="" dir="auto" translate="no">'+escape(account.emailHint||'')+'</span>'+(!account.emailHint?ownerLeaf('Аккаунт'):'')+' · <span dir="ltr">'+escape(account.id.slice(-6))+'</span></p></div></div><span class="teacher-state '+(account.active?'is-active':'')+'">'+ownerLeaf(account.active?'Преподаватель':account.revision?'Доступ отозван':'Доступ не назначен')+'</span><div class="cabinet-card-actions"></div>');return el;}

 function button(container,label,handler,secondary=false){const b=host.ownerDocument.createElement('button');b.type='button';b.className='button'+(secondary?' secondary':'');ownerText(b,label);b.onclick=handler;container.append(b);return b;}
 async function change(account,grant){if(busy)return;controls(true);ownerText(status,grant?'Назначаем преподавателя…':'Отзываем доступ…');try{await call(grant?'teacher-assign':'teacher-revoke',{userId:account.id,expectedRevision:account.revision});if(!active())return;profile.replaceChildren();form.reset();lookup++;ownerText(status,grant?'Роль преподавателя назначена. Учебные разделы пока остаются закрытыми.':'Роль преподавателя отозвана.');await load();}catch(error){if(active())ownerError(status,error);}finally{if(active())controls(false);}}
 function drawProfile(account){profile.replaceChildren();const el=card(account),actions=el.querySelector('.cabinet-card-actions');if(account.active){const p=host.ownerDocument.createElement('p');p.className='cabinet-muted';ownerText(p,'Этот аккаунт уже назначен преподавателем.');el.append(p);}else button(actions,account.revision?'Назначить снова':'Назначить преподавателем',()=>void change(account,true));profile.append(el);}
 async function load(){const result=await call('teacher-list');if(!active())return;roster.replaceChildren();if(!result.teachers.length){const p=host.ownerDocument.createElement('p');p.className='cabinet-empty';ownerText(p,'Пока нет назначенных преподавателей.');roster.append(p);return;}for(const account of result.teachers){const el=card(account),actions=el.querySelector('.cabinet-card-actions');if(account.active)button(actions,'Отозвать доступ',()=>{if(busy)return;actions.replaceChildren();const p=host.ownerDocument.createElement('p');p.className='teacher-revoke-note';uiSet(p,'ownerUi.revokeTeacherQuestion','Закрыть доступ {name} к роли преподавателя?',{name:account.nickname});actions.append(p);button(actions,'Подтвердить отзыв',()=>void change(account,false));button(actions,'Отмена',()=>void reload(),true);},true);else button(actions,'Назначить снова',()=>drawProfile(account),true);roster.append(el);}}
 async function reload(){if(busy)return;controls(true);try{await load();}catch(error){if(active()){ownerError(status,error);roster.replaceChildren();button(roster,'Повторить загрузку',()=>void reload(),true);}}finally{if(active())controls(false);}}
 form.onsubmit=async event=>{event.preventDefault();if(busy)return;const ticket=++lookup;controls(true);profile.replaceChildren();ownerText(status,'Ищем аккаунт…');try{const result=await call('teacher-lookup',{nickname:form.elements.nickname.value.trim()});if(!active()||ticket!==lookup)return;profile.replaceChildren();for(const account of result.accounts){const el=card(account);if(!account.active)button(el.querySelector('.cabinet-card-actions'),account.revision?'Назначить снова':'Назначить преподавателем',()=>void change(account,true));profile.append(el);}ownerText(status,result.truncated?'Много совпадений. Уточните ник.':result.accounts.length>1?'Найдено несколько аккаунтов. Выберите нужный профиль и подтвердите назначение.':'Проверьте найденный профиль, затем подтвердите назначение.');}catch(error){if(active()&&ticket===lookup)ownerError(status,error);}finally{if(active())controls(false);}};
 form.elements.nickname.oninput=()=>{lookup++;profile.replaceChildren();uiRaw(status,'');};
 void reload();return()=>{stopOwnerUi(host);disposed=true;lookup++;host.replaceChildren();};
}
